        try { saveAllData(); } catch (e) {}
        try { if (String(currentChatSessionId) === sid && typeof renderChatMessages === 'function') renderChatMessages(); } catch (e) {}
        try { if (typeof renderChatCharList === 'function') renderChatCharList(); } catch (e) {}
        return m;
