                const id = _si(w, ms); T.id = id; window.__gyxTimers.push(T); return id;
            };
            window.clearInterval = function (id) { const L = window.__gyxTimers || [], i = L.findIndex(t => t.id === id); if (i >= 0) L.splice(i, 1); return _ci(id); };
